(()=>{'use strict';
 const $=s=>document.querySelector(s),weekStart=()=>{const tehran=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Tehran'}));tehran.setHours(0,0,0,0);tehran.setDate(tehran.getDate()-((tehran.getDay()+1)%7));return tehran},iso=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),tehranDate=value=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value)).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return parts.year+'-'+parts.month+'-'+parts.day},taskDate=t=>t.due||tehranDate(t.created_at),inWeek=t=>{const date=taskDate(t),start=iso(weekStart()),end=new Date(weekStart());end.setDate(end.getDate()+7);return !!date&&date>=start&&date<iso(end)};
 let windowMode='week';
 function supported(){return ['mine','all'].includes(scope)&&phase==='all'&&!String(search||'').trim()}
 function rows(){return [...document.querySelectorAll('#sharedContent tr,#sharedContent .desk-task-card')].map(node=>{const button=node.querySelector('[data-task],[data-shared-card]'),key=button?.dataset.task||button?.dataset.sharedCard;return {node,task:tasks.find(t=>t.id===key)}}).filter(x=>x.task)}
 function viewPicker(){document.querySelector('#weekViewPicker')?.remove();if(!supported())return;const heading=$('#sharedContent .desk-shared-heading');if(!heading)return;const picker=document.createElement('div');picker.id='weekViewPicker';picker.className='week-view-picker';picker.innerHTML='<small>بازهٔ کارها</small><div role="group" aria-label="بازه نمایش کارها"><button type="button" data-week-view="week" class="'+(windowMode==='week'?'active':'')+'">هفتهٔ جاری</button><button type="button" data-week-view="all" class="'+(windowMode==='all'?'active':'')+'">همه</button></div>';picker.querySelectorAll('[data-week-view]').forEach(button=>button.onclick=()=>{windowMode=button.dataset.weekView;apply()});heading.append(picker)}
 function clear(){document.querySelector('#weeklyTaskWindow')?.remove();document.querySelectorAll('[data-week-hidden]').forEach(n=>n.removeAttribute('data-week-hidden'));document.querySelectorAll('.desk-lane[data-week-lane-hidden]').forEach(n=>{n.removeAttribute('data-week-lane-hidden');n.hidden=false})}
 function apply(){clear();viewPicker();if(!supported()||windowMode==='all'){document.dispatchEvent(new Event('samandis-week-window'));return}const hidden=rows().filter(({task})=>!inWeek(task));if(!hidden.length){document.dispatchEvent(new Event('samandis-week-window'));return}for(const {node} of hidden)node.setAttribute('data-week-hidden','');for(const lane of document.querySelectorAll('.desk-lane')){const cards=[...lane.querySelectorAll('.desk-task-card')];if(cards.length&&cards.every(card=>card.hasAttribute('data-week-hidden'))){lane.setAttribute('data-week-lane-hidden','');lane.hidden=true}}const host=$('#sharedContent .clarity-list')||$('#sharedContent .shared-empty')||$('#sharedContent');if(host){const button=document.createElement('button');button.type='button';button.id='weeklyTaskWindow';button.className='weekly-task-window';button.innerHTML='<span><strong>نمایش بیشتر</strong><small>نمای فعلی: هفتهٔ جاری · '+fa(hidden.length)+' کار دیگر</small></span><i>›</i>';button.onclick=()=>{windowMode='all';apply()};host.after(button)}document.dispatchEvent(new Event('samandis-week-window'))}
 const oldRender=render;render=function(...args){const result=oldRender(...args);queueMicrotask(apply);return result};const oldTasks=renderTasks;renderTasks=function(...args){const result=oldTasks(...args);queueMicrotask(apply);return result};apply();
})();
